mkdir -p /tmp/bot-check && cat > /tmp/bot-check/bot.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
const run = promisify(execFile);
const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g3-1/bot.mjs';
const bot = await import(BOT);
const { recordUnsubscribe, recordResubscribe, mayEmail } = bot;
const NOW = new Date('2026-10-22T12:00:00Z');
const mk = async () => { process.env.STATE_DIR = await mkdtemp(path.join(tmpdir(), 'bot-')); };
const mkt = (to) => mayEmail({ to, kind: 'marketing' }, NOW);
const tx = (to) => mayEmail({ to, kind: 'transactional' }, NOW);
const T = (s) => new Date(`2026-10-${s}`);

test('exports exactly three functions', () => {
  assert.deepEqual(Object.keys(bot).sort(), ['mayEmail', 'recordResubscribe', 'recordUnsubscribe']);
});
test('unsubscribe blocks marketing, not transactional', async () => {
  await mk();
  await recordUnsubscribe('Ann@Example.com', T('10T10:00:00Z'));
  assert.deepEqual(await mkt('ann@example.com'), { allowed: false, reason: 'unsubscribed' });
  assert.deepEqual(await tx('ann@example.com'), { allowed: true, reason: null });
});
test('clean address is allowed', async () => {
  await mk();
  assert.deepEqual(await mkt('new@example.com'), { allowed: true, reason: null });
});
test('resubscribe after unsubscribe re-allows marketing', async () => {
  await mk();
  await recordUnsubscribe('<EMAIL>', T('10T10:00:00Z'));
  await recordResubscribe('<EMAIL>', T('10T11:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).allowed, true);
});
test('out of order: resub first, late unsub older than resub does not block', async () => {
  await mk();
  await recordResubscribe('<EMAIL>', T('10T11:00:00Z'));
  await recordUnsubscribe('<EMAIL>', T('10T10:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).allowed, true);
});
test('out of order: late unsub newer than resub blocks', async () => {
  await mk();
  await recordResubscribe('<EMAIL>', T('10T11:00:00Z'));
  await recordUnsubscribe('<EMAIL>', T('10T12:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).reason, 'unsubscribed');
});
test('tie: same instant counts as unsubscribed', async () => {
  await mk();
  await recordResubscribe('<EMAIL>', T('10T11:00:00Z'));
  await recordUnsubscribe('<EMAIL>', T('10T11:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).reason, 'unsubscribed');
});
test('duplicate unsubscribe delivery is harmless', async () => {
  await mk();
  for (let i = 0; i < 3; i++) await recordUnsubscribe('<EMAIL>', T('10T10:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).reason, 'unsubscribed');
});
test('header form and gmail aliases map to one person', async () => {
  await mk();
  await recordUnsubscribe('"Pat" <<EMAIL>>', T('10T10:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).reason, 'unsubscribed');
  assert.equal((await mkt('<EMAIL>')).reason, 'unsubscribed');
});
test('non-gmail dots are significant', async () => {
  await mk();
  await recordUnsubscribe('<EMAIL>', T('10T10:00:00Z'));
  assert.equal((await mkt('<EMAIL>')).allowed, true);
  assert.equal((await mkt('<EMAIL>')).allowed, false);
});
test('invalid recipient and bad inputs', async () => {
  await mk();
  assert.deepEqual(await mkt('not-an-address'), { allowed: false, reason: 'invalid_recipient' });
  await assert.rejects(recordUnsubscribe('bad', T('10T10:00:00Z')));
  await assert.rejects(recordUnsubscribe('<EMAIL>', 'nope'));
  await assert.rejects(mayEmail({ to: '<EMAIL>', kind: 'promo' }, NOW));
  await assert.rejects(mayEmail({ to: '<EMAIL>', kind: 'marketing' }, 'now'));
});
test('missing STATE_DIR: marketing fails closed, transactional still goes', async () => {
  delete process.env.STATE_DIR;
  assert.deepEqual(await mkt('<EMAIL>'), { allowed: false, reason: 'suppression_state_unavailable' });
  assert.deepEqual(await tx('<EMAIL>'), { allowed: true, reason: null });
  await assert.rejects(recordUnsubscribe('<EMAIL>', T('10T10:00:00Z')));
});
test('corrupt event file fails closed for marketing', async () => {
  await mk();
  await recordUnsubscribe('<EMAIL>', T('10T10:00:00Z'));
  const { readdir, writeFile } = await import('node:fs/promises');
  const { createHash } = await import('node:crypto');
  const dir = path.join(process.env.STATE_DIR, 'suppression', createHash('sha256').update('<EMAIL>').digest('hex'));
  const [f] = (await readdir(dir)).filter(n => n.endsWith('.json'));
  await writeFile(path.join(dir, f), '{"kind":"unsubscribe"');
  assert.equal((await mkt('<EMAIL>')).reason, 'suppression_state_unavailable');
});
test('multi-process race and restart: all workers agree', async () => {
  await mk();
  const script = `
    const b = await import(${JSON.stringify(BOT)});
    const [op, email, ms] = process.argv.slice(1);
    const at = new Date(Number(ms));
    if (op === 'u') await b.recordUnsubscribe(email, at); else await b.recordResubscribe(email, at);
  `;
  const base = Date.parse('2026-10-10T00:00:00Z');
  const jobs = [];
  // 40 processes race; unsub at base+1000 is the latest among unsubs, resub at base+500 is older -> blocked.
  for (let i = 0; i < 20; i++) jobs.push(run(process.execPath, ['--input-type=module', '-e', script, 'u', 'Race@Example.com', String(base + (i === 7 ? 1000 : i))]));
  for (let i = 0; i < 20; i++) jobs.push(run(process.execPath, ['--input-type=module', '-e', script, 'r', 'race@example.com', String(base + (i === 3 ? 500 : 0))]));
  await Promise.all(jobs);
  // Fresh process = restarted worker
  const check = `const b = await import(${JSON.stringify(BOT)});
    const r = await b.mayEmail({to:'RACE@example.com', kind:'marketing'}, new Date()); console.log(JSON.stringify(r));`;
  const { stdout } = await run(process.execPath, ['--input-type=module', '-e', check], { env: process.env });
  assert.deepEqual(JSON.parse(stdout), { allowed: false, reason: 'unsubscribed' });
});
EOF
cd /tmp/bot-check && node --test bot.test.mjs 2>&1 | tail -60
